function toggleNavGroup(button) {
  const group = button.closest(".nav-group");
  if (!group) return;
  const shouldExpand = group.classList.contains("is-collapsed");
  document.querySelectorAll(".nav-group").forEach((navGroup) => {
    const isExpandedGroup = shouldExpand && navGroup === group;
    navGroup.classList.toggle("is-collapsed", !isExpandedGroup);
    navGroup.querySelector(".nav-group-items")?.toggleAttribute("inert", !isExpandedGroup);
    navGroup.querySelector("[data-nav-toggle]")?.setAttribute("aria-expanded", String(isExpandedGroup));
  });
}

